Input:
{
  property_public_id: 'EB-VK1013',  // EasyBroker public_id
  conversation_id: UUID | null
}
Output:
{
  conversation_id, property_public_id, tags,
  owner_agent_id, owner_name, owner_number,
  resolved: boolean
}
Resolves the per-property owner agent from EasyBroker tags via
resolve_agent_from_tags(). resolved=false => caller routes to manager.

parameters.jsCode:
// Extract the tags array from the EasyBroker property payload.
// On API error (continueOnFail) tags is empty => resolver returns no owner.
const trig = $('When Called').first().json;
const resp = $input.first().json || {};
const tags = Array.isArray(resp.tags) ? resp.tags : [];

// Build a Postgres text[] literal: {"tag1","tag2"}
const tags_pg = '{' + tags
  .map(t => '"' + String(t).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"')
  .join(',') + '}';

return [{
  json: {
    property_public_id: trig.property_public_id || null,
    conversation_id: trig.conversation_id || null,
    tags,
    tags_pg
  }
}];

// Shape the resolver output. No matching row => resolved:false (manager route).
const ctx = $('Extract Tags').first().json;
const row = $input.first().json || {};
const owner_agent_id = row.owner_agent_id || null;

return [{
  json: {
    conversation_id: ctx.conversation_id,
    property_public_id: ctx.property_public_id,
    tags: ctx.tags,
    owner_agent_id,
    owner_name: row.owner_name || null,
    owner_number: row.owner_number || null,
    resolved: !!owner_agent_id
  }
}];
